:host {
  --lab-kit-ink: var(--lab-ink, #20303a);
  --lab-kit-muted: var(--lab-muted, #687780);
  --lab-kit-line: var(--lab-line, #cbd6dc);
  --lab-kit-surface: var(--lab-surface, #ffffff);
  --lab-kit-panel: var(--lab-paper, #f6f9fb);
  --lab-kit-accent: var(--lab-accent, #2b7ac3);
  --lab-kit-accent-soft: var(--lab-accent-soft, #e9f3fb);
  --lab-kit-good: var(--lab-good, #23794d);
  --lab-kit-good-soft: var(--lab-good-soft, #e9f7ef);
  --lab-kit-warn: var(--lab-warn, #8b6419);
  --lab-kit-warn-soft: var(--lab-warn-soft, #fff7d9);
  --lab-kit-bad: var(--lab-bad, #a3443d);
  --lab-kit-bad-soft: var(--lab-bad-soft, #fff0ef);
  --lab-kit-focus: var(--lab-focus, #1f6fb4);
  --lab-kit-focus-ring: rgba(31, 111, 180, .28);
  --lab-kit-canvas: var(--lab-paper, #fbfbfd);
  --lab-kit-canvas-grid: #e7ebee;
  --lab-kit-canvas-grid-size: 24px;
  --lab-kit-radius: var(--lab-panel-radius, 12px);
  --lab-kit-control-radius: var(--lab-control-radius, 8px);
  --lab-kit-shadow: var(--lab-panel-shadow, 0 5px 16px rgba(32, 48, 58, .08));
}
[data-lab-kit-focus]:focus-visible {
  outline: 3px solid var(--lab-kit-focus-ring);
  outline-offset: 2px;
}.workspace-row{gap:24px}.reference-zone,.build-zone{border:0;border-radius:0;background:transparent}.tray{margin-top:18px;padding:14px 0 0;border:0;border-top:1px solid var(--lab-line);border-radius:0;background:transparent}.reference-caption{display:none}.drop-message{font-size:var(--lab-type-body,14px);line-height:1.45}.tray-head span,.tray-return{font-size:var(--lab-type-body,14px);line-height:1.45}.diff-line .work-status.good{color:var(--lab-good)}
.canvas .workspace-row{gap:16px}
.canvas .reference-zone{border:1px solid var(--lab-line,#d2d2d7);border-radius:8px;background:var(--lab-surface-muted,#f7f8fa)}
.stage-zone-heading{position:relative;z-index:5;display:flex;flex-direction:column;align-items:flex-start;gap:4px;padding:12px 12px 8px}
.stage-zone-heading .zone-label,.stage-zone-heading .zone-value{position:static;margin:0;font-family:var(--lab-font-sans,inherit);font-size:12px;font-weight:400;line-height:1.45;text-transform:none;letter-spacing:normal}
.stage-zone-heading .zone-label{color:var(--lab-muted,#6e6e73)}
.stage-zone-heading .zone-value{color:var(--lab-ink,#1d1d1f)}
.canvas .reference-stage{padding:12px}
.canvas .tray{padding:12px;border:1px solid var(--lab-line-subtle,#e7e8eb);border-radius:8px;background:var(--lab-surface,#fff)}
.tray .tray-head{display:flex;align-items:center;flex-wrap:wrap;gap:8px 12px}
.tray .tray-head>div:first-child{flex:1 1 220px}
.tray .tray-head strong{font-size:12px;font-weight:500}
.tray .tray-head span{margin-top:4px;font-size:12px;font-weight:400;line-height:1.45}
.tray .tray-return{display:none;margin:0;color:var(--lab-accent-ink,#315b91);font-size:12px;font-weight:400;line-height:1.45}
.tray.return-ready{border-color:var(--lab-accent-line,#9fb4d6)}
.tray.return-ready .tray-return{display:block}
.tray.return-over{background:var(--lab-accent-soft,#eef2fa);outline:2px solid var(--lab-accent-line,#9fb4d6);outline-offset:2px}
.canvas .reference-zone,.canvas .build-zone,.canvas .tray,.canvas .loose-field{border-radius:12px}
.canvas .build-zone{border:1px solid var(--lab-line,#d2d2d7);background:var(--lab-surface,#fff)}
.canvas .guide-highlight{border-radius:12px;outline:2px solid var(--lab-accent,#5277b8)!important;outline-offset:3px;box-shadow:0 0 0 4px rgba(82,119,184,.12);animation:sequenceTargetPulse 2s ease-in-out infinite}
.loose-field.guide-highlight .loose-tile{animation:none}
@keyframes sequenceTargetPulse{0%,100%{box-shadow:0 0 0 4px rgba(82,119,184,.10)}50%{box-shadow:0 0 0 9px rgba(82,119,184,.22)}}
.build-model{position:relative;width:100%;height:calc(7 * var(--cell) + 48px)}
.build-model .build-grid{transform:translate(-50%,-50%);border:0;outline:1px solid var(--lab-line,#d2d2d7)}
.build-model .build-stage-shell{inset:0}
.inspector .decision-card.good{border-color:var(--lab-good-line,#9cc7aa);background:var(--lab-good-surface,#f7fcf8)}
.calc-panel .calc-step.good{border-color:var(--lab-good-line,#9cc7aa);background:var(--lab-good-surface,#f7fcf8)}
.calc-panel .calc-step.good::after{color:var(--lab-good-ink,#225f43)}
.lab-activity-bar .run-actions>button.active{background:var(--lab-accent-hover,#4569aa);border-color:var(--lab-accent-hover,#4569aa);color:#fff}
@keyframes workingBorderPulse{0%,100%{border-color:var(--lab-needed-line,#d8c36a);box-shadow:0 0 0 0 rgba(216,195,106,0)}50%{border-color:var(--lab-needed,#946200);box-shadow:0 0 0 3px rgba(216,195,106,.18)}}
@keyframes workingAttention{0%,100%{border-color:var(--lab-needed-line,#d8c36a);box-shadow:none}50%{border-color:var(--lab-needed,#946200);box-shadow:0 0 0 3px rgba(216,195,106,.18)}}
@keyframes workingAttention{0%,100%{border-color:var(--lab-needed-line,#d8c36a);box-shadow:none}50%{border-color:var(--lab-needed,#946200);box-shadow:0 0 0 3px rgba(216,195,106,.18)}}
@keyframes workingAttention{0%,100%{border-color:var(--lab-needed-line,#d8c36a);box-shadow:none}50%{border-color:var(--lab-needed,#946200);box-shadow:0 0 0 3px rgba(216,195,106,.18)}}
@keyframes workingAttention{0%,100%{border-color:var(--lab-needed-line,#d8c36a);box-shadow:none}50%{border-color:var(--lab-needed,#946200);box-shadow:0 0 0 3px rgba(216,195,106,.18)}}
@keyframes workingAttention{0%,100%{border-color:var(--lab-needed-line,#d8c36a);box-shadow:none}50%{border-color:var(--lab-needed,#946200);box-shadow:0 0 0 3px rgba(216,195,106,.18)}}
@keyframes labGuideAttention{0%,100%{box-shadow:0 0 0 4px rgba(82,119,184,.10)}50%{box-shadow:0 0 0 9px rgba(82,119,184,.22)}}
